  1	/**
  2	 * Organization creation, settings updates and deletion; seeds the owner membership and the free subscription.
  3	 *
  4	 * Must call (do not reimplement): assertCan, assertOrgScope, emit, uniqueSlug, assertValidSlug
  5	 */
  6	import { emit } from "@/lib/event-bus";
  7	import { assertCan } from "@/lib/permissions";
  8	import { assertValidSlug, uniqueSlug } from "@/lib/slug";
  9	import { assertOrgScope } from "@/lib/tenant";
 10	import * as memberRepo from "@/server/repositories/member-repository";
 11	import * as orgRepo from "@/server/repositories/organization-repository";
 12	import * as projectRepo from "@/server/repositories/project-repository";
 13	import * as subscriptionRepo from "@/server/repositories/subscription-repository";
 14	import * as usageRepo from "@/server/repositories/usage-repository";
 15	import { record } from "./activity-service";
 16	import { envelope, orgResource, requireFound } from "./_support";
 17	import type {
 18	  CreateOrganizationInput,
 19	  DeleteOrganizationInput,
 20	  UpdateOrganizationInput,
 21	} from "@/schemas/organization";
 22	import type { OrgId, UserId } from "@/types/common";
 23	import type { Actor } from "@/types/member";
 24	import type { Organization, OrganizationSummary } from "@/types/organization";
 25	
 26	/**
 27	 * Creates an organization and everything it cannot exist without: the owner's
 28	 * membership row and a subscription. Sign-up and "create another workspace"
 29	 * both land here, which is why it takes a bare `ownerId` rather than an
 30	 * `Actor` — there is no membership to build one from yet.
 31	 */
 32	export async function createOrganization(
 33	  ownerId: UserId,
 34	  input: CreateOrganizationInput,
 35	): Promise<Organization> {
 36	  assertValidSlug(input.slug);
 37	
 38	  const taken = await orgRepo.listTakenOrgSlugs(input.slug);
 39	  const slug = uniqueSlug(input.slug, taken);
 40	
 41	  const org = await orgRepo.insertOrg({ ...input, slug }, ownerId);
 42	
 43	  const owner = await memberRepo.insertMember(org.id, ownerId, "owner", null);
 44	  await subscriptionRepo.insertSubscription(org.id, input.plan, "monthly");
 45	  await usageRepo.recomputeUsage(org.id);
 46	
 47	  await emit("member.joined", {
 48	    ...envelope(org.id, ownerId),
 49	    memberId: owner.id,
 50	    userId: ownerId,
 51	    role: owner.role,
 52	  });
 53	
 54	  return org;
 55	}
 56	
 57	export async function updateOrganization(
 58	  actor: Actor,
 59	  input: UpdateOrganizationInput,
 60	): Promise<Organization> {
 61	  assertOrgScope(actor, input.orgId);
 62	  assertCan(actor, "org:update", orgResource(input.orgId));
 63	
 64	  const updated = await orgRepo.updateOrg(input.orgId, input);
 65	
 66	  // Settings changes are audited directly: the event bus has no
 67	  // `organization.updated` key, and inventing one would widen the contract.
 68	  await record(input.orgId, "organization.updated", {
 69	    actorId: actor.userId,
 70	    subjectKind: "organization",
 71	    subjectId: updated.id,
 72	    projectId: null,
 73	    summary: `${updated.name} settings updated`,
 74	  });
 75	
 76	  return updated;
 77	}
 78	
 79	/**
 80	 * Deletion is a soft delete guarded by a typed confirmation, the same shape
 81	 * GitHub uses: the caller has to retype the slug.
 82	 */
 83	export async function deleteOrganization(
 84	  actor: Actor,
 85	  input: DeleteOrganizationInput,
 86	): Promise<Organization> {
 87	  assertOrgScope(actor, input.orgId);
 88	  assertCan(actor, "org:delete", orgResource(input.orgId));
 89	
 90	  const org = requireFound(
 91	    await orgRepo.findOrgById(input.orgId),
 92	    "Organization",
 93	    input.orgId,
 94	  );
 95	
 96	  if (org.slug !== input.confirmSlug) {
 97	    throw new Error("The confirmation does not match this organization's slug");
 98	  }
 99	
100	  return orgRepo.archiveOrg(input.orgId);
101	}
102	
103	/** The header/shell payload: the org plus the counters the sidebar shows. */
104	export async function getOrganizationSummary(
105	  actor: Actor,
106	  orgId: OrgId,
107	): Promise<OrganizationSummary> {
108	  assertOrgScope(actor, orgId);
109	  assertCan(actor, "org:read", orgResource(orgId));
110	
111	  const organization = requireFound(
112	    await orgRepo.findOrgById(orgId),
113	    "Organization",
114	    orgId,
115	  );
116	
117	  return {
118	    organization,
119	    usage: await usageRepo.getUsage(orgId),
120	    memberCount: await memberRepo.countActiveMembers(orgId),
121	    projectCount: await projectRepo.countProjects(orgId),
122	  };
123	}
124	
125	/** The org switcher's list; no `Actor` exists until one is chosen. */
126	export async function listOrganizationsForUser(
127	  userId: UserId,
128	): Promise<readonly Organization[]> {
129	  return orgRepo.listOrgsForUser(userId);
130	}
131	
132	export async function resolveOrgBySlug(
133	  slug: string,
134	): Promise<Organization | null> {
135	  return orgRepo.findOrgBySlug(slug);
136	}
  1	/**
  2	 * Slug generation and validation, shared by organization creation, project
  3	 * creation and the "is this slug free?" checks in both the Zod schemas and the
  4	 * repositories. One implementation so the client preview and the server
  5	 * insertion can never disagree.
  6	 */
  7	
  8	export const SLUG_PATTERN = /^[a-z0-9]+(?:-[a-z0-9]+)*$/;
  9	
 10	export const SLUG_MIN_LENGTH = 2;
 11	export const SLUG_MAX_LENGTH = 48;
 12	
 13	/** Slugs the router or marketing pages already claim. */
 14	export const RESERVED_SLUGS: readonly string[] = [
 15	  "admin",
 16	  "api",
 17	  "auth",
 18	  "billing",
 19	  "blog",
 20	  "changelog",
 21	  "dashboard",
 22	  "docs",
 23	  "help",
 24	  "login",
 25	  "logout",
 26	  "new",
 27	  "pricing",
 28	  "register",
 29	  "settings",
 30	  "static",
 31	  "support",
 32	  "taskflow",
 33	  "www",
 34	];
 35	
 36	/** Lowercases, strips diacritics and punctuation, collapses to `a-z0-9-`. */
 37	export function slugify(input: string): string {
 38	  return input
 39	    .normalize("NFKD")
 40	    .replace(/[\u0300-\u036f]/g, "")
 41	    .toLowerCase()
 42	    .replace(/[^a-z0-9]+/g, "-")
 43	    .replace(/^-+|-+$/g, "")
 44	    .slice(0, SLUG_MAX_LENGTH)
 45	    .replace(/-+$/g, "");
 46	}
 47	
 48	export function isValidSlug(value: string): boolean {
 49	  return (
 50	    value.length >= SLUG_MIN_LENGTH &&
 51	    value.length <= SLUG_MAX_LENGTH &&
 52	    SLUG_PATTERN.test(value)
 53	  );
 54	}
 55	
 56	export function isReservedSlug(value: string): boolean {
 57	  return RESERVED_SLUGS.includes(value);
 58	}
 59	
 60	export class InvalidSlugError extends Error {
 61	  readonly code = "validation_failed" as const;
 62	
 63	  constructor(readonly value: string, readonly reason: string) {
 64	    super(`Invalid slug "${value}": ${reason}`);
 65	    this.name = "InvalidSlugError";
 66	  }
 67	}
 68	
 69	export function assertValidSlug(value: string): void {
 70	  if (!isValidSlug(value)) {
 71	    throw new InvalidSlugError(value, "must match ^[a-z0-9]+(-[a-z0-9]+)*$");
 72	  }
 73	  if (isReservedSlug(value)) {
 74	    throw new InvalidSlugError(value, "is reserved");
 75	  }
 76	}
 77	
 78	/**
 79	 * Derives a slug from `input` that collides with nothing in `taken`, by
 80	 * appending `-2`, `-3`, … Repositories pass their existing slug set in.
 81	 */
 82	export function uniqueSlug(input: string, taken: Iterable<string>): string {
 83	  const base = slugify(input) || "item";
 84	  const used = new Set(taken);
 85	  if (!used.has(base) && !isReservedSlug(base)) return base;
 86	
 87	  for (let suffix = 2; suffix < 1_000; suffix += 1) {
 88	    const candidate = `${base.slice(0, SLUG_MAX_LENGTH - 5)}-${suffix}`;
 89	    if (!used.has(candidate) && !isReservedSlug(candidate)) return candidate;
 90	  }
 91	  throw new InvalidSlugError(base, "exhausted unique suffixes");
 92	}
 93	
 94	/** Project keys are the short uppercase prefix shown on issue numbers (TF-12). */
 95	export function projectKeyFromName(name: string): string {
 96	  const words = name.trim().split(/\s+/).filter(Boolean);
 97	  const letters =
 98	    words.length >= 2
 99	      ? words.slice(0, 3).map((w) => w[0] ?? "").join("")
100	      : (words[0] ?? "task").slice(0, 3);
101	  return letters.toUpperCase().replace(/[^A-Z0-9]/g, "").slice(0, 4) || "TASK";
102	}
  1	import { z } from "zod";
  2	import {
  3	  SLUG_MAX_LENGTH,
  4	  SLUG_MIN_LENGTH,
  5	  SLUG_PATTERN,
  6	  isReservedSlug,
  7	} from "@/lib/slug";
  8	
  9	/**
 10	 * Slug validation, reusing the predicates from `@/lib/slug` so the form
 11	 * preview, the Server Action and the repository uniqueness check all agree.
 12	 */
 13	export const slugSchema = z
 14	  .string()
 15	  .min(SLUG_MIN_LENGTH)
 16	  .max(SLUG_MAX_LENGTH)
 17	  .regex(SLUG_PATTERN, "use lowercase letters, digits and single hyphens")
 18	  .refine((value) => !isReservedSlug(value), {
 19	    message: "that slug is reserved",
 20	  });
 21	
 22	export const projectKeySchema = z
 23	  .string()
 24	  .min(2)
 25	  .max(4)
 26	  .regex(/^[A-Z][A-Z0-9]*$/, "use 2-4 uppercase letters or digits");
 27	
 28	export type SlugInput = z.infer<typeof slugSchema>;

