  1	/**
  2	 * Global user rows. The only repository that is NOT tenant scoped — users exist across organizations.
  3	 */
  4	import { eq, inArray } from "drizzle-orm";
  5	import { newId } from "@/lib/id";
  6	import { getDb, users } from "@/server/db";
  7	import { toIsoTimestamp } from "@/types/common";
  8	import { toUser } from "./_mappers";
  9	import type { UpdateProfileInput } from "@/schemas/member";
 10	import type { UserId } from "@/types/common";
 11	import type { User } from "@/types/member";
 12	
 13	export async function findUserById(userId: UserId): Promise<User | null> {
 14	  const rows = getDb().select().from(users).where(eq(users.id, userId)).all();
 15	  const row = rows.at(0);
 16	  return row ? toUser(row) : null;
 17	}
 18	
 19	/**
 20	 * Addresses are matched as stored. The auth schemas lowercase what the forms
 21	 * submit, so a lookup already arrives in the stored spelling.
 22	 */
 23	export async function findUserByEmail(email: string): Promise<User | null> {
 24	  const rows = getDb()
 25	    .select()
 26	    .from(users)
 27	    .where(eq(users.email, email))
 28	    .all();
 29	  const row = rows.at(0);
 30	  return row ? toUser(row) : null;
 31	}
 32	
 33	export async function insertUser(input: {
 34	  email: string;
 35	  name: string;
 36	  passwordHash: string;
 37	}): Promise<User> {
 38	  const stamp = toIsoTimestamp(new Date());
 39	  const row = getDb()
 40	    .insert(users)
 41	    .values({
 42	      id: newId(),
 43	      // Stored as typed: the welcome email is addressed with this value.
 44	      email: input.email,
 45	      name: input.name,
 46	      passwordHash: input.passwordHash,
 47	      avatarUrl: null,
 48	      timezone: "UTC",
 49	      emailVerifiedAt: null,
 50	      createdAt: stamp,
 51	      updatedAt: stamp,
 52	    })
 53	    .returning()
 54	    .get();
 55	
 56	  return toUser(row);
 57	}
 58	
 59	export async function updateUser(
 60	  userId: UserId,
 61	  patch: UpdateProfileInput,
 62	): Promise<User> {
 63	  const row = getDb()
 64	    .update(users)
 65	    .set({
 66	      ...(patch.name === undefined ? {} : { name: patch.name }),
 67	      ...(patch.avatarUrl === undefined ? {} : { avatarUrl: patch.avatarUrl }),
 68	      ...(patch.timezone === undefined ? {} : { timezone: patch.timezone }),
 69	      updatedAt: toIsoTimestamp(new Date()),
 70	    })
 71	    .where(eq(users.id, userId))
 72	    .returning()
 73	    .get();
 74	
 75	  if (!row) throw new Error(`User ${userId} not found`);
 76	  return toUser(row);
 77	}
 78	
 79	/**
 80	 * The password hash never travels on the `User` domain type — nothing outside
 81	 * `AuthService` may see it — so login reads it through this narrow accessor.
 82	 *
 83	 * Not in the manifest: added because `User` deliberately omits the column and
 84	 * credential login has no other way to reach it.
 85	 */
 86	export async function findPasswordHash(
 87	  userId: UserId,
 88	): Promise<string | null> {
 89	  const row = getDb()
 90	    .select({ passwordHash: users.passwordHash })
 91	    .from(users)
 92	    .where(eq(users.id, userId))
 93	    .get();
 94	  return row?.passwordHash ?? null;
 95	}
 96	
 97	/** Counterpart of `findPasswordHash`, used by the password-reset flow. */
 98	export async function updatePasswordHash(
 99	  userId: UserId,
100	  passwordHash: string,
101	): Promise<void> {
102	  getDb()
103	    .update(users)
104	    .set({ passwordHash, updatedAt: toIsoTimestamp(new Date()) })
105	    .where(eq(users.id, userId))
106	    .run();
107	}
108	
109	/** Batch fetch used by every list view that decorates rows with their author. */
110	export async function findUsersByIds(
111	  userIds: readonly UserId[],
112	): Promise<readonly User[]> {
113	  if (userIds.length === 0) return [];
114	  const rows = getDb()
115	    .select()
116	    .from(users)
117	    .where(inArray(users.id, [...userIds]))
118	    .all();
119	  return rows.map(toUser);
120	}
  1	/**
  2	 * Returns the current `SessionPrincipal`, or 401.
  3	 *
  4	 * Owner D. Used by the client to re-check the session after a tab has been
  5	 * asleep. It returns the principal, never the token — the cookie is httpOnly
  6	 * and stays that way.
  7	 *
  8	 * Must call (do not reimplement): getSessionPrincipal
  9	 */
 10	
 11	import { getSessionPrincipal } from "@/lib/session";
 12	import { errorResponse, failure } from "@/app/api/_lib/responses";
 13	
 14	export const dynamic = "force-dynamic";
 15	
 16	export async function GET(request: Request): Promise<Response> {
 17	  void request;
 18	
 19	  try {
 20	    const principal = await getSessionPrincipal();
 21	    if (principal === null) {
 22	      return failure("unauthorized", "No active session.");
 23	    }
 24	
 25	    return Response.json({
 26	      userId: principal.userId,
 27	      email: principal.email,
 28	      activeOrgId: principal.activeOrgId,
 29	      expiresAt: principal.expiresAt,
 30	    });
 31	  } catch (error) {
 32	    return errorResponse(error);
 33	  }
 34	}

