 1	/**
 2	 * The result envelope every Server Action and Route Handler returns. Actions
 3	 * never throw for expected failures — they return `ActionResult` so the client
 4	 * form layer can render field errors without an error boundary.
 5	 */
 6	
 7	export type ErrorCode =
 8	  | "unauthorized"
 9	  | "forbidden"
10	  | "not_found"
11	  | "validation_failed"
12	  | "conflict"
13	  | "rate_limited"
14	  | "plan_limit_exceeded"
15	  | "tenant_scope_violation"
16	  | "internal_error";
17	
18	export interface AppErrorShape {
19	  readonly code: ErrorCode;
20	  readonly message: string;
21	  /** Zod-style field path → messages, for react-hook-form to consume. */
22	  readonly fieldErrors?: Readonly<Record<string, readonly string[]>>;
23	  readonly meta?: Readonly<Record<string, string | number | boolean>>;
24	}
25	
26	export type Result<T, E = AppErrorShape> =
27	  | { readonly ok: true; readonly data: T }
28	  | { readonly ok: false; readonly error: E };
29	
30	/** What a Server Action returns to a `useActionState` reducer. */
31	export type ActionResult<T> = Result<T> & {
32	  /** Monotonic token so the client can distinguish two identical results. */
33	  readonly submittedAt?: string;
34	};
35	
36	export interface ApiErrorBody {
37	  readonly error: AppErrorShape;
38	}
39	
40	export function ok<T>(data: T): Result<T> {
41	  return { ok: true, data };
42	}
43	
44	export function err<T = never>(error: AppErrorShape): Result<T> {
45	  return { ok: false, error };
46	}
47	
48	export function isOk<T, E>(
49	  result: Result<T, E>,
50	): result is { ok: true; data: T } {
51	  return result.ok;
52	}
 1	import { sqliteTable, text, uniqueIndex } from "drizzle-orm/sqlite-core";
 2	import { idColumn, timestampColumns } from "./_shared";
 3	
 4	/** Users are global, not tenant-scoped: one account can join many orgs. */
 5	export const users = sqliteTable(
 6	  "users",
 7	  {
 8	    id: idColumn(),
 9	    email: text("email").notNull(),
10	    name: text("name").notNull(),
11	    passwordHash: text("password_hash").notNull(),
12	    avatarUrl: text("avatar_url"),
13	    timezone: text("timezone").notNull().default("UTC"),
14	    emailVerifiedAt: text("email_verified_at"),
15	    ...timestampColumns,
16	  },
17	  (table) => [uniqueIndex("users_email_idx").on(table.email)],
18	);
19	
20	export const sessions = sqliteTable(
21	  "sessions",
22	  {
23	    id: idColumn(),
24	    userId: text("user_id").notNull(),
25	    activeOrgId: text("active_org_id"),
26	    tokenHash: text("token_hash").notNull(),
27	    expiresAt: text("expires_at").notNull(),
28	    ...timestampColumns,
29	  },
30	  (table) => [uniqueIndex("sessions_token_idx").on(table.tokenHash)],
31	);
32	
33	export const passwordResetTokens = sqliteTable("password_reset_tokens", {
34	  id: idColumn(),
35	  userId: text("user_id").notNull(),
36	  tokenHash: text("token_hash").notNull(),
37	  expiresAt: text("expires_at").notNull(),
38	  usedAt: text("used_at"),
39	  ...timestampColumns,
40	});
41	
42	export type UserRow = typeof users.$inferSelect;
43	export type NewUserRow = typeof users.$inferInsert;
44	export type SessionRow = typeof sessions.$inferSelect;

