cat > tests/zz-tmp-signup.test.ts <<'EOF'
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("./server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("./server/_support/doubles/misc")).loggerModule);
vi.mock("@/lib/rate-limit", async () => (await import("./server/_support/doubles/misc")).rateLimitModule);

import { subscribe } from "@/lib/event-bus";
import { toAppError, HTTP_STATUS_BY_CODE } from "@/lib/errors";
import { isReservedSlug, isValidSlug } from "@/lib/slug";
import { updateOrganizationSchema } from "@/schemas/organization";
import { getDb, users, organizations } from "@/server/db";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import * as userRepo from "@/server/repositories/user-repository";
import { login, register } from "@/server/services/auth-service";
import { rateLimitState } from "./server/_support/doubles/misc";
import { useTemporaryDatabase } from "./server/_support/fixtures";

let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); });
afterAll(() => cleanup());
afterEach(() => { rateLimitState.allowed = true; });

const PW = "Correct1Horse2";
const input = (name: string, email: string) => ({ name, email, password: PW, confirmPassword: PW, acceptTerms: true as const });
const counts = () => ({
  users: getDb().select().from(users).all().length,
  orgs: getDb().select().from(organizations).all().length,
});

describe("sign-up", () => {
  it("works for awkward names", async () => {
    const out: Record<string, string> = {};
    for (const [i, name] of ["Admin", "Billing", "Support", "Taskflow", "Al", "J", "山田", "山田", "Ö", "Admin"].entries()) {
      const { org } = await register(input(name, `p${i}@example.com`));
      out[`${i}:${name}`] = org.slug;
      expect(isValidSlug(org.slug)).toBe(true);
      expect(isReservedSlug(org.slug)).toBe(false);
      expect(org.name).toBe(`${name}'s workspace`);
      const sub = await subscriptionRepo.findSubscription?.(org.id);
      void sub;
    }
    console.log(out);
  });

  it("emits member.joined once", async () => {
    let n = 0;
    const off = subscribe("member.joined", async () => { n += 1; });
    await register(input("Event Person", "event@example.com"));
    off();
    expect(n).toBe(1);
  });

  it("is case-insensitive on addresses", async () => {
    const { user } = await register(input("Phone Person", "Phone.Person@Example.COM"));
    expect(user.email).toBe("phone.person@example.com");
    const before = counts();
    const err = await register(input("Phone Person", "phone.person@example.com")).catch((e) => e);
    expect(toAppError(err).code).toBe("conflict");
    expect(err.code).toBe("conflict");
    expect(counts()).toEqual(before);
    const { user: u2 } = await login({ email: "PHONE.person@example.com", password: PW, rememberMe: false });
    expect(u2.id).toBe(user.id);
    expect((await userRepo.findUserByEmail("phone.PERSON@example.com"))?.id).toBe(user.id);
  });

  it("finds a legacy mixed-case row", async () => {
    getDb().$client.prepare("INSERT INTO users (id, email, name, password_hash, timezone, created_at, updated_at) VALUES ('01HZZZLEGACYAAAAAAAAAAAAAA','Legacy@Example.com','L','x','UTC','2026-01-01T00:00:00.000Z','2026-01-01T00:00:00.000Z')").run();
    expect((await userRepo.findUserByEmail("legacy@example.com"))?.email).toBe("Legacy@Example.com");
    const err = await register(input("L", "legacy@EXAMPLE.com")).catch((e) => e);
    expect(toAppError(err).code).toBe("conflict");
  });

  it("fits long names", async () => {
    const name = "Maximiliana Alexandrovna Konstantinopolskaya-Wellington von Hohenzollern III".padEnd(80, "x");
    expect(name.length).toBe(80);
    const { org } = await register(input(name, "long@example.com"));
    console.log(org.name, org.name.length, org.slug, org.slug.length);
    expect(org.name.length).toBeLessThanOrEqual(64);
    expect(org.name.endsWith("'s workspace")).toBe(true);
    expect(updateOrganizationSchema.safeParse({ orgId: org.id, name: org.name }).success).toBe(true);
    const slugs = [];
    for (let i = 0; i < 4; i += 1) slugs.push((await register(input(name, `long${i}@example.com`))).org.slug);
    console.log(slugs);
    expect(new Set(slugs).size).toBe(4);
    const emoji = "😀".repeat(40);
    const { org: e } = await register(input(emoji, "emoji@example.com"));
    expect(e.name.length).toBeLessThanOrEqual(64);
    expect(e.name).toBe("😀".repeat(26) + "'s workspace");
  });

  it("throttles", async () => {
    rateLimitState.allowed = false;
    const before = counts();
    const err = await register(input("Bot", "bot@example.com")).catch((e) => e);
    expect(toAppError(err).code).toBe("rate_limited");
    expect(HTTP_STATUS_BY_CODE[toAppError(err).code]).toBe(429);
    expect(counts()).toEqual(before);
    const lerr = await login({ email: "bot@example.com", password: PW, rememberMe: false }).catch((e) => e);
    expect(toAppError(lerr).code).toBe("rate_limited");
    console.log(toAppError(lerr));
  });
});
EOF
